#include <bits/stdc++.h>
using namespace std;

const __int128 MOD = 998244353;

__int128 mod_pow(__int128 base, __int128 exp, __int128 mod) {
    __int128 result = 1;
    __int128 b = base % mod;
    __int128 e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        e >>= 1;
    }
    return result;
}

__int128 mod_inverse(__int128 a, __int128 m) {
    // Fermat's little theorem since m is prime
    return mod_pow(a, m - 2, m);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    // Read input
    string line;
    getline(cin, line);
    // int testCases = 1; // as per code, testCases is fixed to 1
    int testCases = 1;
    while (testCases--) {
        getline(cin, line);
        stringstream ss(line);
        long long n, m;
        ss >> n >> m;
        getline(cin, line);
        ss.clear(); ss.str(line);
        long long l, r;
        ss >> l >> r;
        long long rangeLength = r - l;
        long long evenCount = rangeLength / 2 + 1;
        long long oddCount = (rangeLength + 1) / 2;
        __int128 total = (__int128)n * m;
        if ((n * m) % 2 == 1) {
            __int128 base = (__int128)(rangeLength + 1);
            __int128 res = mod_pow(base, total, MOD);
            cout << (long long)res << "\n";
        } else {
            __int128 sum_pow = (mod_pow(evenCount + oddCount, total, MOD) + mod_pow(evenCount - oddCount, total, MOD)) % MOD;
            __int128 inv_two = mod_inverse(2, MOD);
            __int128 result = (sum_pow * inv_two) % MOD;
            cout << (long long)result << "\n";
        }
    }
    return 0;
}

